CORE = r'''

  /* ---------- 4c. 产品表现（ASIN 日报）：解析 / 期化 / 聚合核心 ---------- */
  /*PERF-CORE-BEGIN*/
  var PERF_METRICS = ['sess', 'pv', 'ord', 'units', 'sales', 'imp', 'clk', 'spend', 'adsales', 'adord'];
  function perfHeaderResolve(raw) {
    var k = String(raw == null ? '' : raw).replace(/[\s\r\n*　]/g, '').toLowerCase();
    if (!k) return null;
    var M = { '日期': 'ds', 'asin': 'asin', '父asin': 'pasin', '店铺': 'shop', '国家': 'country', '品名': 'name',
      'sessions-total': 'sess', 'pv-total': 'pv', '订单量': 'ord', '销量': 'units', '销售额': 'sales',
