  }
  /* aoa → { rows, issues:{fatal?,badDate[],noAsin,unknown}, dates[], countries[], asinCount } */
  function buildPerfRows(aoa) {
    if (!aoa || !aoa.length) return { rows: [], issues: { fatal: '文件为空' } };
    var hdrIdx = 0, best = -1, map = null, unknown = 0;
    for (var i = 0; i < Math.min(10, aoa.length); i++) {
      var mm = {}, un = 0, hit = 0;
      (aoa[i] || []).forEach(function (h, ci) {
