function makeDB(db){
  const mk = (sql,args)=>({
    bind:(...a)=>mk(sql,a),
    first:()=>{ const s=db.prepare(sql); const r=args.length?s.get(...args):s.get(); return r===undefined?null:r },
    all:()=>{ const s=db.prepare(sql); return { results: args.length?s.all(...args):s.all() } },
