// 从产权证明 PDF 中提取「不动产权属证书号」如 粤（2021）深圳市不动产权第1234567号 → 1234567
async function extractCertNo (filename) {
  if (!filename || !/\.pdf$/i.test(filename)) return ''
  const fp = path.join(UPLOAD_DIR, filename)
  if (!fs.existsSync(fp)) return ''
  try {
    const data = await pdfParse(fs.readFileSync(fp))
    const t = (data.text || '').replace(/\s+/g, '')
    const m = t.match(/不动产权第([0-9A-Za-z]+)号/) ||
              t.match(/不动产权证?第([0-9A-Za-z]+)号/) ||
              t.match(/第([0-9]{5,})号/)
    return m ? m[1] : ''
  } catch (e) { console.error('PDF 证书号提取失败：', e.message); return '' }
}",
