  submitSignature (fields, files, editToken) {
    const et = editToken || app().globalData.editToken || ''
    const fsm = wx.getFileSystemManager()
    const toDataUrl = (p) => new Promise((resolve) => {
      if (!p) return resolve('')
      const mExt = /\.(\w+)(?:\?|$)/.exec(p)
      let ext = (mExt ? mExt[1] : 'png').toLowerCase()
      const mime = ext === 'jpg' ? 'jpeg' : ext
      fsm.readFile({
        filePath: p, encoding: 'base64',
        success: r => resolve('data:image/' + mime + ';base64,' + r.data),
        fail: () => resolve('')
      })
    })
    return Promise.all([toDataUrl(files.cert), toDataUrl(files.idFront), toDataUrl(files.idBack), toDataUrl(files.sign)])
      .then(([certB64, idFrontB64, idBackB64, signB64]) => req('/api/mp/signature', {
        method: 'POST',
        data: Object.assign({}, fields, { editToken: et, certB64, idFrontB64, idBackB64, signB64 })
      }))
      .then(r => { if (r && r.editToken) app().setEditToken(r.editToken); return r })
  },",
