  const capacity = Math.floor(data.length / 4) * 3
  if (bits > capacity) return false
  let bi = 0
  for (let px = 0; px < data.length && bi < bits; px += 4) {
    for (let ch = 0; ch < 3 && bi < bits; ch++) {
      const byte = bytes[bi >> 3]
      const bit = (byte >> (7 - (bi & 7))) & 1
      const idx = px + ch
      data[idx] = (data[idx] & 0xFE) | bit
      bi++
    }
  }
  return true
}

