  "message": "FAQ批量导入脚本",
  "input": {
    "description": "FAQ批量导入脚本",
    "file_text": "#!/usr/bin/env node
/* 批量导入常见问题（一次性使用）
 *
 * 用法：
 *   cd /root/yezhu-web/server
 *   node import-faq.js 你的发起人口令
 *
 * 说明：
 *   · 通过后台正式接口导入，走的是和手工添加完全一样的通道，安全；
 *   · 自动跳过已存在的相同问题，重复执行不会产生重复条目；
 *   · 只新增，不会删除或改动任何已有问答。
 */
const fs = require('fs')
const path = require('path')

const PASS = process.argv[2]
const FILE = process.argv[3] || path.join(__dirname, 'faq-security.json')
const PORT = process.env.PORT || 3999
const BASE = 'http://127.0.0.1:' + PORT

if (!PASS) {
  console.error('\n用法：node import-faq.js 你的发起人口令\n')
  process.exit(1)
}
if (!fs.existsSync(FILE)) {
  console.error('\n找不到问答文件：' + FILE + '\n请把 faq-security.json 放到同一目录下。\n')
  process.exit(1)
}

let items
try {
  items = JSON.parse(fs.readFileSync(FILE, 'utf8'))
} catch (e) {
  console.error('\n问答文件格式有误：' + e.message + '\n')
  process.exit(1)
}
if (!Array.isArray(items) || !items.length) {
  console.error('\n问答文件为空。\n')
  process.exit(1)
}

async function post (url, body, token) {
  const headers = { 'content-type': 'application/json' }
  if (token) headers['authorization'] = 'Bearer ' + token
  const r = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) })
  const d = await r.json().catch(() => null)
  if (!r.ok || (d && d.ok === false)) throw new Error((d && d.msg) || ('HTTP ' + r.status))
  return d && d.data
}

;(async () => {
  console.log('\n连接本机服务 ' + BASE + ' …')
  let token
  try {
    const r = await post(BASE + '/api/admin/login', { passcode: PASS })
    token = r.token
    console.log('✅ 登录成功')
  } catch (e) {
    console.error('❌ 登录失败：' + e.message)
    console.error('   请检查口令是否正确、服务是否在运行（pm2 list）。\n')
    process.exit(1)
  }

  // 取已有问答，避免重复导入
  let exist = []
  try {
    const r = await fetch(BASE + '/api/faq')
    const d = await r.json()
    exist = ((d && d.data && d.data.list) || []).map(x => String(x.q || '').trim())
  } catch (e) {}

  let added = 0, skipped = 0, failed = 0
  for (const it of items) {
    const q = String(it.q || '').trim()
    if (!q || !it.a) { failed++; continue }
    if (exist.indexOf(q) >= 0) {
      console.log('  ⏭  已存在，跳过：' + q.slice(0, 26))
      skipped++
      continue
    }
    try {
      await post(BASE + '/api/admin/faq', {
        group: it.group || '其他',
        q,
        a: it.a,
        pinned: false
      }, token)
      console.log('  ✅ 已添加：' + q.slice(0, 26))
      added++
    } catch (e) {
      console.log('  ❌ 失败：' + q.slice(0, 26) + ' —— ' + e.message)
      failed++
    }
  }

  console.log('\n完成：新增 ' + added + ' 条，跳过 ' + skipped + ' 条，失败 ' + failed + ' 条。')
  console.log('现在打开网站「答疑」页即可看到新增的「数据安全与监督」分组。\n')
  process.exit(failed ? 1 : 0)
})()
