{
  "message": "检验每页词表中的词是否都能在叙事中被高亮匹配到",
  "input": {
    "command": "cd /home/claude && cat > test_hl.js << 'JSEOF'
const fs=require('fs');
const DATA=JSON.parse(fs.readFileSync('palace_data.json','utf8'));
const escRe=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const variants=t=>t.split('/').map(x=>x.trim()).filter(Boolean);
function buildRe(words){
  const vs=[]; words.forEach(w=>variants(w.t).forEach(v=>vs.push(v)));
  if(!vs.length) return null;
  vs.sort((a,b)=>b.length-a.length);
  return new RegExp('(?<![A-Za-z\\u00C0-\\u024F])('+vs.map(escRe).join('|')+')(?![A-Za-z\\u00C0-\\u024F])','gi');
}
let problems=0, totalTerms=0, totalHits=0;
DATA.forEach(s=>{
  if(!s.words.length) return;
  const re=buildRe(s.words);
  const hits=new Set((s.story.match(re)||[]).map(x=>x.toLowerCase()));
  totalHits+=hits.size;
  const missing=[];
  s.words.forEach(w=>{
    totalTerms++;
    const vs=variants(w.t).map(v=>v.toLowerCase());
    if(!vs.some(v=>hits.has(v))) missing.push(w.t);
  });
  if(missing.length){ problems++; console.log(s.page, '未在叙事中高亮:', missing.join(' | ')); }
});
console.log('---'); console.log('词条总数', totalTerms, '有问题的页', problems);
JSEOF
node test_hl.js",
