import pathlib
p = pathlib.Path('build.py'); s = p.read_text(encoding='utf-8')
old = s[s.index("const q = document.getElementById('q')"):s.index("</script></body></html>")]
new = """const q = document.getElementById('q'), hits = document.getElementById('hits');
function unmark(root){
  root.querySelectorAll('mark').forEach(m => {
    const t = document.createTextNode(m.textContent);
    m.replaceWith(t);
  });
  root.normalize();          // 合并被拆碎的文本节点，否则反复搜索会越切越碎
}
function mark(node, k){
  // 只在文本节点上做替换。直接改 innerHTML 会把行内的时间戳 <span> 一起抹掉。
  const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
  const targets = [];
  while (walker.nextNode()) {
    if (walker.currentNode.nodeValue.includes(k)) targets.push(walker.currentNode);
  }
  targets.forEach(tn => {
    const frag = document.createDocumentFragment();
    tn.nodeValue.split(k).forEach((part, i) => {
      if (i) { const m = document.createElement('mark'); m.textContent = k; frag.append(m); }
      if (part) frag.append(document.createTextNode(part));
    });
    tn.replaceWith(frag);
  });
  return targets.length;
}
q.addEventListener('input', () => {
  const k = q.value.trim();
  unmark(document.getElementById('doc'));
  if (!k) { document.querySelectorAll('section').forEach(s=>s.classList.remove('hide'));
            hits.textContent=''; return; }
  let n = 0;
  document.querySelectorAll('section').forEach(sec => {
    let found = 0;
    sec.querySelectorAll('p.line, .ocr, h2').forEach(node => { found += mark(node, k); });
    n += found;
    sec.classList.toggle('hide', !found);
  });
  hits.textContent = n ? `命中 ${n} 处` : '无匹配';
});
"""
s = s.replace(old, new)
p.write_text(s, encoding='utf-8'); print('ok')
