function simInv(pd, rd, dd){
  const T=100; let inv=200;
  const invs=[], sales=[], orders=[], perceived=[];
  for(let t=0;t<=T;t++){
    const demand = t<=25 ? 20 : 22;
    const s = Math.min(inv, demand);
    sales.push(s);
    let per;
    if(pd<=0) per = s;
    else { let sum=0,n=0; for(let k=Math.max(0,sales.length-pd);k<sales.length;k++){sum+=sales[k];n++;} per=sum/n; }
    perceived.push(per);
    const desired = per*10;
    const disc = desired - inv;
    const ord = Math.max(0, rd<=0 ? per+disc : per + disc/rd);
    orders.push(ord);
    const del = (t < dd || dd===0) ? (dd===0 ? ord : 20) : orders[t-dd];
    inv = Math.max(0, inv + del - s);
    invs.push(inv);
  }
  return invs;
}
