    "new_str": "def graft_outline(reader, writer, start0, end0):
    """把落在 [start0,end0) 内的书签移植进 writer,保持层级。
    父项不在区间内时,子项上提到根,避免生成目标不可解析的悬空书签。"""
    def walk(items, parent):
        for it in items:
            if isinstance(it, list):
                walk(it, parent)          # 未知父级 -> 沿用当前父
                continue
            try:
                pg = reader.get_destination_page_number(it)
            except Exception:
                pg = None
            if pg is None or not (start0 <= pg < end0):
                continue
            try:
                writer.add_outline_item(str(it.title), pg - start0, parent=parent)
            except Exception:
                pass
    try:
        src = reader.outline
    except Exception:
        return
    # 逐层处理:顶层项建好后,其子列表挂到该项下
    def layered(items, parent):
        last = None
        for it in items:
            if isinstance(it, list):
                layered(it, last if last is not None else parent)
                continue
            try:
                pg = reader.get_destination_page_number(it)
            except Exception:
                pg = None
            if pg is None or not (start0 <= pg < end0):
                last = parent          # 父不在区间 -> 子项上提
                continue
            try:
                last = writer.add_outline_item(str(it.title), pg - start0,
                                               parent=parent)
            except Exception:
                last = parent
    layered(src, None)


def build_buf(reader, start0, end0, compress=False):
    """构造 [start0, end0) 的子文档,返回 BytesIO。0-based,右开。"""
    w = PdfWriter()
    w.append(reader, pages=(start0, end0), import_outline=False)
    graft_outline(reader, w, start0, end0)
    if compress:"
