{
  "message": "用 node 复核计算器与压力测试的核心数学",
  "input": {
    "command": "cd /tmp && cat > sanity.js << 'EOF'
const IB={name:"IBKR",haircut:0.01,borrow:5.12,cash:3.13,cashFree:10000,key:"ib"};
const SW={name:"Schwab",haircut:0.075,borrow:11.30,cash:0.35,cashFree:0,key:"sw"};
const f=n=>(n<0?"-$":"$")+Math.abs(Math.round(n)).toLocaleString("en-US");

function run(nav,yld,notP,prem,cyc,asg,days,st){
  const notional=nav*notP/100, tbill=nav*yld/100;
  const premInc=notional*prem/100*cyc, assigned=notional*asg/100, rolls=4;
  console.log(`\n── nav=${f(nav)} yld=${yld}% notional=${notP}% prem=${prem}%x${cyc} assigned=${asg}% days=${days} stateTax=${st}%`);
  console.log(`   T-bill利息 ${f(tbill)} | 权利金 ${f(premInc)} | 接货额 ${f(assigned)}`);
  [IB,SW].forEach(bk=>{
    const carry=assigned*Math.max(0,(bk.borrow-yld))/100*days/360;
    const comm=bk.key==="ib"?rolls*Math.max(5,nav*0.00002):0;
    const cashInt=bk.key==="ib"?Math.max(0,nav-bk.cashFree)*bk.cash/100:nav*bk.cash/100;
    const taxCash=cashInt*st/100;
    const netB=tbill-carry-comm+premInc, netA=cashInt-taxCash+premInc;
    const req=notional*0.20, coll=nav*(1-bk.haircut);
    console.log(`   ${bk.name.padEnd(7)} B(T-bill)=${f(netB)} (${(netB/nav*100).toFixed(2)}%) | A(现金)=${f(netA)} (${(netA/nav*100).toFixed(2)}%) | 差 ${f(netB-netA)} | carry ${f(-carry)} | 用率 ${(req/coll*100).toFixed(1)}%`);
  });
}
// 默认参数
